import {areas,DemoRepository} from './data.js';
import {CloudRepository} from './cloud.js';
let repo=new CloudRepository();let view='overview',areaId='weld',employeeId=null,selectedJob='74812',jobTab='mine',search='';
const $=s=>document.querySelector(s),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const active=j=>j.status!=='Complete',employee=id=>repo.state.employees.find(e=>e.id===id),area=id=>areas.find(a=>a.id===id),jobsFor=id=>repo.state.jobs.filter(j=>j.area===id&&active(j)),initials=n=>n.split(' ').map(s=>s[0]).join(''),pct=j=>Math.round(j.done/j.qty*100),pill=s=>`<span class="pill ${({'In progress':'progress','Needs work':'need','Ready':'ready','Blocked':'blocked','Complete':'complete'})[s]||''}">${esc(s)}</span>`;
function toast(s){$('#toast').textContent=s;$('#toast').style.display='block';clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>$('#toast').style.display='none',3500)}
function personState(e){const js=repo.state.jobs.filter(j=>j.employee===e.id&&active(j));return e.need?'Needs work':js.some(j=>j.status==='In progress')?'In progress':js.length?'Assigned':'Needs work'}
function navigate(v){view=v;search='';render();if(v==='badge')$('#badge').focus()}
function shell(body){const isEmp=view==='employee';$('#app').innerHTML=`<div class="shell"><aside class="sidebar"><div class="brand">TABET<span> /</span></div><div class="brand-sub">PRODUCTION SYSTEM</div><div class="nav-label">WORKSPACE</div><nav><button class="nav-btn ${['overview','area'].includes(view)?'active':''}" data-nav="overview"><span class="nav-icon">▦</span>Production overview</button><button class="nav-btn ${['badge','employee'].includes(view)?'active':''}" data-nav="badge"><span class="nav-icon">▣</span>Employee station</button><button class="nav-btn ${view==='settings'?'active':''}" data-nav="settings"><span class="nav-icon">⚙</span>Display settings</button></nav><div class="sidebar-foot"><span class="dot"></span> ${repo.mode==='cloud'?'Supabase connected':'Local demo'}<br><span style="color:#778ba3">Norfolk, Virginia · CAGE 88829</span><br><span style="font-size:9px">TPS / VERSION 0.2</span></div></aside><div class="workspace"><header><div class="crumb">TPS <span style="margin:0 12px;color:#c0c8d2">/</span> <b>${isEmp?'Employee station':view==='badge'?'Badge access':view==='settings'?'Configuration':'Production control'}</b></div><div class="header-right"><button class="demo" id="connection-mode">${repo.mode==='cloud'?'SHARED SAMPLE DATA':'LOCAL DEMO · CONNECT'}</button><span class="date">${new Date().toLocaleDateString('en-US',{month:'short',day:'numeric',year:'numeric'})}</span><span class="avatar">${isEmp?initials(employee(employeeId).name):'AD'}</span><span class="user-label">${isEmp?esc(employee(employeeId).name):repo.mode==='cloud'?'Open workspace':'Demo admin'}</span></div></header><main>${body}<footer><span>TABET MANUFACTURING · PRODUCTION SYSTEM</span><span>${repo.mode==='cloud'?'Supabase · shared workspace':'Local browser demo'}</span></footer></main></div></div>`;document.querySelectorAll('[data-nav]').forEach(b=>b.onclick=()=>{employeeId=null;navigate(b.dataset.nav)});bind()}
function stat(label,value,foot,cls=''){return `<div class="stat"><div class="stat-label">${label}<span>↗</span></div><div class="stat-value">${value}</div><div class="stat-foot ${cls}">${foot}</div></div>`}
function overview(){const js=repo.state.jobs.filter(active),es=repo.state.employees,working=es.filter(e=>personState(e)==='In progress').length,needs=es.filter(e=>personState(e)==='Needs work').length;return `<div class="title-row"><div><div class="eyebrow">SHOP FLOOR / OVERVIEW</div><h1>Production at a glance</h1><p class="subtitle">Every area. Every job. Your people, connected.</p></div><button class="primary" id="open-badge">▣ &nbsp; Open employee station</button></div><div class="stats">${stat('JOBS ON THE FLOOR',js.length,'Across '+areas.length+' production areas')}${stat('EMPLOYEES WORKING',working,es.length+' employees across both shifts','green')}${stat('NEED WORK',needs,'Ready for their next assignment','amber')}${stat('JOBS ON HOLD',js.filter(j=>j.status==='Blocked').length,'Require supervisor attention','amber')}</div><div class="section-head"><div><h2>Production areas</h2><p>Select an area to see jobs and shift assignments.</p></div><span class="subtitle">${areas.length} areas &nbsp; · &nbsp; All shifts</span></div><div class="areas">${areas.map(a=>{const jobs=jobsFor(a.id),people=es.filter(e=>e.area===a.id),busy=people.filter(e=>personState(e)==='In progress').length,need=people.filter(e=>personState(e)==='Needs work').length;return `<button class="area-card" data-area="${a.id}"><div class="area-top"><div class="area-heading"><div class="area-symbol">${a.icon}</div><div><div class="area-name">${esc(a.name)}</div><div class="area-code">${esc(a.code)}</div></div></div>${need?pill(need+' need work'):pill('On track')}</div><div class="area-metrics"><div><strong>${jobs.length}</strong><small>ACTIVE JOBS</small></div><div><strong>${busy}<span style="font-size:14px;color:#a6b0bd"> / ${people.length}</span></strong><small>PEOPLE WORKING</small></div></div><div class="area-bar bar"><span style="width:${busy/Math.max(people.length,1)*100}%"></span></div><div class="area-footer"><span>${jobs.filter(j=>!j.employee&&j.status==='Ready').length} jobs ready to assign</span><b>View area &nbsp; ↗</b></div></button>`}).join('')}</div><div class="section-head"><h2>Recent floor activity</h2><span class="subtitle">${repo.mode==='cloud'?'Shared activity':'This demo workspace'}</span></div>${activity()}`}
function activity(){return `<div class="panel activity">${repo.state.activity.slice(0,4).map(a=>`<div class="activity-row"><span class="dot"></span><span>${esc(a.text)}</span><span class="activity-time">${esc(a.time)}</span></div>`).join('')}</div>`}
function jobTable(js){return `<div class="table-wrap"><table><thead><tr><th>JOB / PART</th><th>STATUS</th><th>ASSIGNED TO</th><th>PROGRESS</th><th>DUE</th><th>PRIORITY</th><th></th></tr></thead><tbody>${js.length?js.map(j=>`<tr><td><button class="job-link" data-detail="${esc(j.id)}"><strong>#${esc(j.id)} · ${esc(j.title)}</strong></button><small>${esc(j.part)} · Rev ${esc(j.revision)}</small></td><td>${pill(j.status)}</td><td>${j.employee?esc(employee(j.employee).name):'<span style="color:#a1aab6">Unassigned</span>'}</td><td><div class="progress-inline"><div class="bar"><span style="width:${pct(j)}%"></span></div>${j.done}/${j.qty}</div></td><td>${esc(j.due)}</td><td>${j.priority==='High'?'<span style="color:#b97e38">↑ High</span>':'Normal'}</td><td><button class="text-btn" data-assign="${esc(j.id)}" ${['Blocked','Complete','In progress'].includes(j.status)?'disabled':''}>${j.employee?'Reassign':'Assign'} ↗</button></td></tr>`).join(''):'<tr><td colspan="7" class="empty">No matching jobs in this area.</td></tr>'}</tbody></table></div>`}
function areaView(){const a=area(areaId),js=repo.state.jobs.filter(j=>j.area===areaId),es=repo.state.employees.filter(e=>e.area===areaId);return `<button class="back" id="back">← &nbsp; All production areas</button><div class="title-row"><div><div class="eyebrow">PRODUCTION AREA / ${esc(a.code)}</div><h1>${esc(a.name)}</h1><p class="subtitle">Current jobs and employee assignments across both shifts.</p></div><button class="primary" id="preview-employee">▣ &nbsp; Employee view</button></div><div class="stats">${stat('ACTIVE JOBS',js.filter(active).length,'Currently in '+a.name)}${stat('IN PROGRESS',js.filter(j=>j.status==='In progress').length,'Work underway','green')}${stat('READY TO ASSIGN',js.filter(j=>!j.employee&&j.status==='Ready').length,'Available to this area')}${stat('NEED WORK',es.filter(e=>personState(e)==='Needs work').length,'Across first and second shift','amber')}</div><section class="panel"><div class="panel-heading"><h2>Jobs in ${esc(a.name)} <small> / ${js.length}</small></h2><input id="job-search" class="search" placeholder="Search jobs or parts…" aria-label="Search jobs or parts" value="${esc(search)}"></div><div id="job-table">${jobTable(js.filter(j=>(j.id+j.title+j.part).toLowerCase().includes(search.toLowerCase())))}</div></section><div class="section-head"><div><h2>People & assignments</h2><p>See who is working and who needs their next job.</p></div><span class="subtitle">${es.length} employees</span></div><div class="shift-grid">${[1,2].map(shift=>`<section class="panel"><div class="panel-heading"><h2>${shift===1?'First':'Second'} shift</h2><small>${es.filter(e=>e.shift===shift).length} employees</small></div>${es.filter(e=>e.shift===shift).map(e=>{const js=repo.state.jobs.filter(j=>j.employee===e.id&&active(j));return `<div class="person"><span class="avatar">${initials(e.name)}</span><div class="person-info"><div class="person-name">${esc(e.name)}</div><div class="person-job">${js.map(j=>'#'+j.id+' · '+j.title).join('<br>')||'Available for an assignment'}</div></div>${pill(personState(e))}</div>`}).join('')||'<div class="empty">No employees on this shift.</div>'}</section>`).join('')}</div>`}
function badgeView(){return `<div class="scan-shell"><div class="eyebrow">EMPLOYEE STATION</div><div class="scan-art">▥</div><h1>Your badge. Your workspace.</h1><p class="subtitle">Scan your badge to open your production area,<br>assigned jobs, and job documents.</p><form id="scan-form" class="scan-panel"><label for="badge">READY FOR BADGE SCAN</label><input id="badge" autocomplete="off" placeholder="Scan or enter badge ID" required><button class="primary" type="submit">Open my workspace &nbsp; →</button><p id="scan-error" class="scan-error" role="alert"></p></form><button id="demo-jonah" class="text-btn">Try Jonah’s demo badge · TPS-1001 &nbsp; →</button><p class="subtitle" style="font-size:10px;margin-top:20px">${repo.mode==='cloud'?'Open station · scan a badge to select your workspace.':'Local demo badge lookup only.'}<br>USB scanners can enter the badge ID followed by Enter.</p></div>`}
function employeeView(){const e=employee(employeeId),a=area(e.area),js=repo.state.jobs.filter(j=>j.area===e.area&&active(j)),mine=js.filter(j=>j.employee===e.id),open=js.filter(j=>!j.employee&&j.status==='Ready'),list=jobTab==='mine'?mine:open;let j=repo.state.jobs.find(j=>j.id===selectedJob&&j.area===e.area&&(j.employee===e.id||(!j.employee&&j.status==='Ready')));if(!j||!active(j)){j=list[0];selectedJob=j?.id}return `<div class="title-row"><div><div class="eyebrow">${a.name.toUpperCase()} / ${e.shift===1?'FIRST':'SECOND'} SHIFT</div><h1>Welcome, ${e.name.split(' ')[0]}.</h1><p class="subtitle">Your work is right here. Select a job to get started.</p></div><div class="actions"><button id="need-work">${e.need?'✓ Work requested':'I need work'}</button><button id="sign-out">End session ↗</button></div></div>${e.need?'<div class="notice">Your supervisor can see that you need work. Your current assignments remain visible below.</div>':''}<div class="employee-layout"><div><div class="panel"><div class="panel-heading"><div class="tabs"><button data-tab="mine" class="${jobTab==='mine'?'active':''}">My jobs (${mine.length})</button><button data-tab="open" class="${jobTab==='open'?'active':''}">Open in area (${open.length})</button></div></div>${list.map(j=>`<button class="job-card ${selectedJob===j.id?'selected':''}" data-job="${esc(j.id)}"><div class="row"><strong style="font-size:11px">#${esc(j.id)}</strong>${pill(j.status)}</div><h3>${esc(j.title)}</h3><p>${esc(j.part)} · Rev ${esc(j.revision)}</p><div class="row"><span style="font-size:10px;color:#8793a1">Due ${esc(j.due)}</span><span style="font-size:10px">${j.done} / ${j.qty} pcs</span></div></button>`).join('')||'<div class="empty">'+(jobTab==='mine'?'No active jobs assigned. Check open jobs or request work.':'No jobs are ready to claim in your area.')+'</div>'}</div><div class="note" style="border:1px solid var(--line);border-radius:6px">${esc(a.name)}<br>Assignments and work status use the same records as the supervisor board.</div></div><section class="panel">${j?jobDetail(j,true):'<div class="empty" style="padding:100px 20px">Select an assigned or open job to view its details.</div>'}</section></div>`}
function jobDetail(j,emp){const own=emp&&j.employee===employeeId;return `<div class="job-detail"><div style="display:flex;justify-content:space-between"><span class="eyebrow" style="margin:0">JOB #${esc(j.id)} / ${j.operation.toUpperCase()}</span>${pill(j.status)}</div><h2>${esc(j.title)}</h2><span class="subtitle">${esc(j.part)} &nbsp; · &nbsp; Revision ${esc(j.revision)}</span><div class="meta-grid"><div><small>QUANTITY</small>${j.done} / ${j.qty} complete</div><div><small>MATERIAL</small>${esc(j.material)}</div><div><small>DUE DATE</small>${esc(j.due)}</div></div><div class="bar"><span style="width:${pct(j)}%"></span></div></div>${repo.state.settings.pdf?`<div class="pdf-toolbar"><span>▤ &nbsp; Sample job document · ${esc(j.part)}</span><a href="sample-job.pdf" target="_blank" rel="noopener">Open PDF ↗</a></div><iframe class="pdf-frame" title="Sample job PDF — demonstration only" src="sample-job.pdf#toolbar=1&view=FitH"></iframe>`:'<div class="empty">Document display disabled by supervisor.</div>'}${repo.state.settings.notes?`<div class="note"><strong>Job instructions</strong><br>${esc(j.notes)}</div>`:''}${emp?`<div class="job-controls">${own?(j.status==='In progress'?`<button class="primary" data-action="pause" data-id="${esc(j.id)}">Ⅱ &nbsp; Pause work</button><button data-action="complete" data-id="${esc(j.id)}">Complete operation</button>`:`<button class="primary" data-action="start" data-id="${esc(j.id)}" ${j.status==='Blocked'?'disabled':''}>▶ &nbsp; ${j.status==='Paused'?'Resume':'Start'} work</button>`):repo.state.settings.claim?`<button class="primary" data-action="claim" data-id="${esc(j.id)}">Assign this job to me</button>`:'<span class="subtitle">Contact your supervisor for assignment.</span>'}</div>`:''}`}
function settingsView(){return `<div class="title-row"><div><div class="eyebrow">ADMIN / CONFIGURATION</div><h1>Employee display settings</h1><p class="subtitle">Configure the information and actions shown at employee stations.</p></div></div><div class="settings-grid"><section class="panel"><div class="panel-heading"><h2>Floor workspace</h2><small>${repo.mode==='cloud'?'Shared configuration':'Demo configuration'}</small></div><div class="setting-body">${[['pdf','Show job PDF viewer'],['notes','Show job instructions'],['claim','Allow employees to claim open jobs in their area']].map(([k,l])=>`<label><input type="checkbox" data-setting="${k}" ${repo.state.settings[k]?'checked':''}>${l}</label>`).join('')}<p>${repo.mode==='cloud'?'Changes are saved to Supabase and shared with stations.':'Changes apply to this browser only.'}</p></div></section><section class="panel"><div class="panel-heading"><h2>Project connections</h2><small>Implementation status</small></div><div class="setting-body"><div class="status-line"><span>Data source</span>${pill(repo.mode==='cloud'?'Supabase PostgreSQL':'Browser demo')}</div><div class="status-line"><span>Supabase</span>${pill(repo.mode==='cloud'?'Connected':'Available — sign in')}</div><div class="status-line"><span>GitHub</span><a href="https://github.com/jonahm-CCS/TPS" target="_blank" rel="noopener">jonahm-CCS/TPS ↗</a></div><div class="status-line"><span>Badge authentication</span>${pill('Supervised selection')}</div><p>Open access is enabled. Badges select the employee workspace. The current PDF is a sample.</p></div></section></div><section class="panel"><div class="panel-heading"><h2>Demo workspace</h2></div><div class="setting-body"><p>${repo.mode==='cloud'?'Cloud records are shared across all stations.':'Reset sample assignments, job progress, activity, and display settings.'}</p>${repo.mode==='cloud'?'<span class="subtitle">Open access enabled</span>':'<button id="reset">Reset demo data</button>'}</div></section>`}
function render(){shell(view==='overview'?overview():view==='area'?areaView():view==='badge'?badgeView():view==='employee'?employeeView():settingsView())}
function bind(){ $('#connection-mode')?.addEventListener('click',()=>{if(repo.mode==='cloud'){navigate('settings')}else{repo=new CloudRepository();boot()}});document.querySelectorAll('[data-area]').forEach(b=>b.onclick=()=>{areaId=b.dataset.area;navigate('area')});$('#open-badge')?.addEventListener('click',()=>navigate('badge'));$('#back')?.addEventListener('click',()=>navigate('overview'));$('#preview-employee')?.addEventListener('click',()=>navigate('badge'));document.querySelectorAll('[data-assign]').forEach(b=>b.onclick=()=>assignDialog(b.dataset.assign));document.querySelectorAll('[data-detail]').forEach(b=>b.onclick=()=>detailDialog(b.dataset.detail));$('#job-search')?.addEventListener('input',e=>{search=e.target.value;$('#job-table').innerHTML=jobTable(repo.state.jobs.filter(j=>j.area===areaId&&(j.id+j.title+j.part).toLowerCase().includes(search.toLowerCase())));document.querySelectorAll('[data-assign]').forEach(b=>b.onclick=()=>assignDialog(b.dataset.assign));document.querySelectorAll('[data-detail]').forEach(b=>b.onclick=()=>detailDialog(b.dataset.detail))});$('#scan-form')?.addEventListener('submit',e=>{e.preventDefault();scan($('#badge').value)});$('#demo-jonah')?.addEventListener('click',()=>scan('TPS-1001'));$('#sign-out')?.addEventListener('click',()=>{employeeId=null;navigate('badge')});$('#need-work')?.addEventListener('click',()=>{if(repo.mode==='cloud'){cloudAction('need',{employee_id:employeeId});return}employee(employeeId).need=true;repo.save(employee(employeeId).name+' requested work');render();toast('Work request visible on the supervisor board')});document.querySelectorAll('[data-tab]').forEach(b=>b.onclick=()=>{jobTab=b.dataset.tab;selectedJob=null;render()});document.querySelectorAll('[data-job]').forEach(b=>b.onclick=()=>{selectedJob=b.dataset.job;render()});document.querySelectorAll('[data-action]').forEach(b=>b.onclick=()=>jobAction(b.dataset.id,b.dataset.action));document.querySelectorAll('[data-setting]').forEach(b=>b.onchange=()=>{if(repo.mode==='cloud'){cloudAction('setting',{setting_key:b.dataset.setting,setting_value:b.checked});return}repo.state.settings[b.dataset.setting]=b.checked;repo.save();toast('Employee display updated')});$('#reset')?.addEventListener('click',()=>{const m=$('#modal');m.innerHTML='<h2>Reset demo workspace?</h2><p class="subtitle">This removes your demo changes and restores sample data in this browser.</p><div class="actions"><button id="cancel">Cancel</button><button class="primary" id="confirm-reset">Reset demo</button></div>';m.showModal();$('#cancel').onclick=()=>m.close();$('#confirm-reset').onclick=()=>{repo.reset();m.close();render();toast('Demo restored')}})}
function scan(code){const e=repo.state.employees.find(e=>e.badge.toUpperCase()===code.trim().toUpperCase());if(!e){$('#scan-error').textContent='Badge not recognized. Try TPS-1001 for Jonah.';return}employeeId=e.id;jobTab='mine';selectedJob=null;navigate('employee')}
function assignDialog(id){const j=repo.state.jobs.find(j=>j.id===id);if(['Blocked','In progress','Complete'].includes(j.status))return;const m=$('#modal');m.innerHTML=`<h2>Assign job #${esc(j.id)}</h2><p class="subtitle">${esc(j.title)} · ${area(j.area).name}</p><label for="assign-person">Employee</label><select id="assign-person"><option value="">Unassigned / open in area</option>${repo.state.employees.filter(e=>e.area===j.area).map(e=>`<option value="${e.id}" ${j.employee===e.id?'selected':''}>${esc(e.name)} · Shift ${e.shift}</option>`).join('')}</select><div class="actions"><button id="cancel">Cancel</button><button class="primary" id="save-assignment">Save assignment</button></div>`;m.showModal();$('#cancel').onclick=()=>m.close();$('#save-assignment').onclick=()=>{if(repo.mode==='cloud'){const id=$('#assign-person').value||null;m.close();cloudAction('assign',{job_id:j.id,employee_id:id});return}j.employee=$('#assign-person').value||null;j.status=j.employee?'Assigned':'Ready';if(j.employee)employee(j.employee).need=false;repo.save('#'+j.id+(j.employee?' assigned to '+employee(j.employee).name:' opened for assignment'));m.close();render();toast('Assignment updated')}}
function detailDialog(id){const j=repo.state.jobs.find(j=>j.id===id),m=$('#modal');m.style.width='780px';m.innerHTML=`<button id="close-detail" style="float:right">Close ×</button>${jobDetail(j,false)}`;m.showModal();$('#close-detail').onclick=()=>{m.close();m.style.width='440px'}}
function jobAction(id,action){if(repo.mode==='cloud'){if(action==='complete'){cloudComplete(id);return}cloudAction(action,{job_id:id,employee_id:employeeId});return}const j=repo.state.jobs.find(j=>j.id===id),e=employee(employeeId);if(!j||j.area!==e.area)return;if(action==='claim'){if(j.employee||j.status!=='Ready'||!repo.state.settings.claim)return;j.employee=e.id;j.status='Assigned';e.need=false;jobTab='mine'}else{if(j.employee!==e.id)return;if(action==='start'){if(!['Assigned','Paused'].includes(j.status))return;if(repo.state.jobs.some(x=>x.employee===e.id&&x.status==='In progress')){toast('Pause your current job before starting another.');return}j.status='In progress';e.need=false}else if(action==='pause'&&j.status==='In progress')j.status='Paused';else if(action==='complete'&&j.status==='In progress'){const m=$('#modal');m.innerHTML=`<h2>Complete this operation?</h2><p class="subtitle">Mark all ${j.qty} pieces of job #${esc(j.id)} complete for ${area(j.area).name}. This demo does not move the job to another area.</p><div class="actions"><button id="cancel">Cancel</button><button id="confirm-complete" class="primary">Complete ${j.qty} pieces</button></div>`;m.showModal();$('#cancel').onclick=()=>m.close();$('#confirm-complete').onclick=()=>{j.done=j.qty;j.status='Complete';repo.save(e.name+' completed #'+j.id);m.close();render();toast('Operation marked complete')};return}else return}repo.save(e.name+' · #'+j.id+' · '+j.status);render();toast('Job updated on the production board')}
window.addEventListener('storage',e=>{if(repo.mode!=='cloud'&&e.key==='tps-demo-v1'){repo.state=new DemoRepository().state;render()}});boot();

async function cloudAction(action,args){
 document.querySelectorAll('button').forEach(b=>b.disabled=true);
 try{await repo.command(action,args);if(action==='claim')jobTab='mine';render();toast('Saved to Supabase')}catch(e){if(repo.state){render();toast(e.message)}else connectionError(e.message)}
}
function cloudComplete(id){const j=repo.state.jobs.find(j=>j.id===id),m=$('#modal');m.innerHTML=`<h2>Complete operation #${esc(id)}?</h2><p class="subtitle">Mark all ${j.qty} pieces complete. This does not move the job to the next production area.</p><div class="actions"><button id="cancel">Cancel</button><button id="confirm-complete" class="primary">Complete operation</button></div>`;m.showModal();$('#cancel').onclick=()=>m.close();$('#confirm-complete').onclick=()=>{m.close();cloudAction('complete',{job_id:id,employee_id:employeeId})}}
function connectionError(error){$('#app').innerHTML=`<div class="scan-shell"><h1>Unable to connect</h1><p class="subtitle">${esc(error)}</p><button id="retry" class="primary">Retry connection</button></div>`;$('#retry').onclick=boot}
async function boot(){try{await repo.load();render()}catch(e){connectionError(e.message)}}
setInterval(async()=>{if(repo.mode!=='cloud'||!repo.state||repo.busy||document.hidden||$('#modal').open)return;try{const old=repo.state.revision;const next=await repo.rpc('tps_snapshot');if(repo.busy)return;if(old!==next.revision){repo.state=next;render()}}catch(e){toast('Unable to refresh shared data. Check your connection.')}},15000);
